package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProgressService { private final CourseService courses;private final FlashcardReviewRepository reviews;private final QuizAttemptRepository attempts;
 public ProgressService(CourseService c,FlashcardReviewRepository r,QuizAttemptRepository a){courses=c;reviews=r;attempts=a;}
 @Transactional(readOnly=true) public ProgressSummary summarize(Long courseId){var course=courses.getCourse(courseId);Map<String,List<Double>> values=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);int activity=0;for(FlashcardReview review:reviews.findByCourseIdOrderByIdAsc(courseId)){String topic=review.getFlashcard().getSources().isEmpty()?"Course material":review.getFlashcard().getSources().getFirst().getDocument().getOriginalFilename();double score=switch(review.getRating()){case INCORRECT->20;case HARD->55;case GOOD->80;case EASY->100;};values.computeIfAbsent(topic,k->new ArrayList<>()).add(score);activity++;}for(QuizAttempt attempt:attempts.findByCourseId(courseId)){String topic="Quiz performance";double score=attempt.getTotalCount()==0?0:100d*attempt.getCorrectCount()/attempt.getTotalCount();values.computeIfAbsent(topic,k->new ArrayList<>()).add(score);activity++;}List<ProgressSummary.TopicProgress> topics=values.entrySet().stream().map(e->{double score=e.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);return new ProgressSummary.TopicProgress(e.getKey(),round(score),status(score),e.getValue().size());}).toList();double overall=topics.stream().mapToDouble(ProgressSummary.TopicProgress::score).average().orElse(0);return new ProgressSummary(course.id(),course.name(),activity,round(overall),status(overall),topics);}
 private String status(double score){return score<60?"WEAK":score<80?"DEVELOPING":"STRONG";}private double round(double value){return Math.round(value*10d)/10d;}
}
